import{_ as s,c as t,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"楊氏易傳卷二十","description":"楊氏易傳 - 楊氏易傳卷二十","frontmatter":{"title":"楊氏易傳卷二十","description":"楊氏易傳 - 楊氏易傳卷二十"},"headers":[],"relativePath":"classics/yangshi/021.md","filePath":"classics/yangshi/021.md"}'),r={name:"classics/yangshi/021.md"};function i(c,a,o,p,d,u){return l(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"楊氏易傳卷二十",tabindex:"-1"},[n("楊氏易傳卷二十 "),e("a",{class:"header-anchor",href:"#楊氏易傳卷二十","aria-label":"Permalink to “楊氏易傳卷二十”"},"​")],-1),e("p",null,"欽定四庫全書",-1),e("p",null,"宋楊簡撰。",-1),e("p",null,"今人言易者必本於乾、坤，陋矣。但見周易之書，不見連山、歸藏之書，故必首乾次坤。不知連山首艮、重艮，故曰連山；歸藏首坤，故曰乾、坤之義。連山，夏后氏之易；歸藏，商人之易。至矣哉！合三易而觀之，而後八卦之妙，大易之用，混然一貫之道，昭昭於天下矣。三方皆易也，三才之變，非一實一，或雜焉，或純焉。純焉其名乾、坤，雜焉其名震、坎、艮、巽、離、兌，皆是物也。一物而八名也，初無大小優劣之間也。形則有大小，道無大小；德則有優劣，道無優劣。或首艮，或首坤，明乎八卦之皆易也。易道則變而為八，其變雖八，其道實一。曰連山宓戲，歸藏黃帝。易卦諸彖言「大矣哉」者，十二卦而已。豫、遁、姤、旅言時義，隨言隨時之義，豈他卦皆無時義哉？豈他卦之時義皆不大哉？坎、暌、蹇言時用，豈他卦皆無時用哉？豈他卦之時用皆不大哉？頤、大過、解、革言時，豈他卦皆非時哉？豈他卦之時皆不大哉？六十四卦皆時也，皆有義也，皆有用也，皆大也。「大矣哉」，蓋嘆其道之大，有言不能盡之意。事無大小，無非易道之妙。聖人偶於此十二卦偶發其數，非此十二卦與他卦特異也，使每卦而言，則不勝其言。愚者執其言，智者通其意，豈特六十四卦皆可稱「大矣哉」，雖三百八十四爻亦皆可稱「大矣哉」！聖人於豫、隨、遁、姤、旅，則猶有義之可言；於坎、暌、蹇，則猶有用之可言。至於頤、大過、解、革，則既不曰「義」，又不曰「用」，止曰「時」而已，夫何以曰「大矣哉」？於戲！此正明以天地無一物一事一時之非易。學者溺於思慮，必求其義。聖人於頤、大過、解輩，盡捐義用，止言其時，而嘆之曰「大矣哉」。使學者無所求索，不容鉤深，即時而悟「大哉」之妙，則事理一貫，精粗一體，孔子「何思何慮」，文王「不識不知」，信矣。需，有孚，光，亨，貞吉。言需得其道，必得所需。需，待也。彼此相孚則應矣。所需待多動乎意，非光也。光如日月之光，無思無為而無所不照，此之謂道。如此人咸信之，故曰「孚」。如此則得所需矣，亨矣。得所需亨通，或放逸失正，故又曰「貞乃吉」。孚與光與正，本非三事，以三言發明道心。一動乎意，則不孚不光不正，謂之人心。故舜曰：「人心惟危。」明其即入於邪，入於兇禍。坤",-1),e("p",null,"六二：「直方大，不習無不利。」直心而往，即易之道。意起則爻而入於邪矣。直心而行，雖遇萬變而不轉易，是之謂「方」。圓則轉，方則不轉。方者，特明不轉之義，非於直之外又有方也。夫道一而已矣，言之不同，初無二致。是道甚大，故曰「大」。是道非學習之所能，故曰「不習」。孟子曰：「人之所不學而能者，其良能也；所不慮而知者，其良知也。」習者勉強，本有者奚俟乎習？此雖人道，即地之道，故曰「地道光」也。光如日月之光，無思無為而無所不照，不光明者也。必入於意，必支而他，必不直方，必昏，必不利。六三「含章可貞」，",-1),e("p",null,"陰雖有美，含之以從王事，弗敢成也。地道也，妻道也，臣道也。地道無成而「代有終」也。惑者往往於是疑其為小，故聖人特發之曰「智光大」也。道一而已，初無小大。",-1),e("p",null,"六四「括囊，無咎無譽」，亦此道也。方時閉塞，義當括囊而謹易道之見於坤，見於謹者也。二言坤道之正，五言坤道之盛，他卦之五多明君象，至於坤，明臣道也，故五止言臣位之極盛。黃者中之義，言乎其得中道也，故曰「通理」。言理以明中，非中自中，理自理也。裳者下服，言乎正人臣之位，居人臣之體也，故曰「正位居體」。明乎得道者必守常分而不犯，此非設飾者所能由中而發於文為，故曰「元吉，文在中也」，言乎文非外飾，乃自中誠而著也。伊周之事，人咸信之，不疑其為非，信其識也。王莽設飾，故卒罹大禍。初之「履霜」，謹微之道；上六之「龍戰」，道之窮也。皆易之道，而有昏明邪正之辨也。",-1),e("p",null,"「坤」之用六，即乾之用九，九六不同而用同。「乾」造始，「坤」代終，始終不同而其大則同，故曰「以大終」也。「至哉」之坤，即「大哉」之乾也，名分不同而道同也。為妻為臣而失道，則不永，則不貞；得其道者，必永必貞。二三四五皆能用六，惟上六不能用六，反為六所用，為形體所使，為勢位所動，故曰初亦不能用六，故為霜，為永，為不善之積，能辨之於早，則能用之矣。小畜柔得位而上下應之，曰小畜。健而巽，剛中而志行，乃亨。小畜，以臣畜君之道也。畜有養義，有止義。以下畜上，非勢之順者，而有道焉，非柔則不敬不順，非得位則不可以有所行，豈有居下位而可以行畜之事者乎？柔雖得位，使人心不悅，雖悅而不至於上下皆悅而應之，亦不能以畜君。天下事未有人心不悅而能行者，而況於畜君乎？故必上下之心鹹應之乃可。其德健則力足以行其事，而無困懾不繼之患；巽則順入乎君心，剛則物莫能變，中則不偏不倚。剛中兩言，足以發明道心之本。人臣能健能巽，而中無其本，亦不能致亨。健矣，巽矣，剛矣，中矣。或所畜之君雖略相應，而諫不盡行，言不盡聽，則臣亦不可謂得行其志，亦不能亨。於戲！物情事理，如上所序，節節如此，曲折如此，乃易之道也。惟柔得位，以明六四之象；眾陽鹹應，有上下應之象。下乾，健象；上巽，巽象；剛中，二五之象；四五剛柔相得，有志行之象。非象自象，道自道也。此正易道之見於小畜六畫者然也。象著其義，彖發其義。柔也，得位也，上下應也，健也，巽也，剛也，中也，志行也，非每事而致其力也。合是數者，以發明易小畜之道。得易道全者，自能當小畜之時，盡小畜之義，自與此彖辭無不合也。有一不合，必於道有虧焉。齊景公悅晏子之對，作君臣相悅之樂，其詩曰：「畜君何尤？」畜君者，好君也，此亦小畜之「小亨」也。何者？晏子猶未有剛中之大本故也。易者，天下之大道。聖人之大道，雖甚賢者，未能盡也。雖高明之士，已得大本，而物情事理，委曲萬變，往往疏略，不能皆盡。孔子自謂「加我數年，五十以學易，可以無大過。」明知夫易者，大聖人之事，應變無窮之道，晚年成德，乃可學也。少讀易大傳，深愛「無思也，無為也，寂然不動，感而遂通天下之故」。竊自念學道必造此妙。及他日讀論語孔子哭顏淵至於慟，從者曰：「子慟矣。」曰：「有慟乎？」則孔子自不知其為慟，殆非所謂無思無為、寂然不動者。至於不自知，則又幾於不清明，懷疑於中，往往一二十年。及承教於象山陸先生，聞舉扇訟之是非，忽覺某心乃如此清明，虛靈妙用之應，無不可者。及後居姚氏喪，哀慟切痛，不可雲喻。既久，略省察曩正哀慟時，乃亦寂然不動，自然不自知，方悟孔子哭顏淵至於慟矣而不自知，正合無思無為之妙，益信吾心有此神用妙用。其哀苦至於如此其極，乃其變化。故易大傳又曰：「變化云為」，不獨其有此心，舉天下萬古之人皆有此心，益信人皆與堯舜禹湯文武周公孔子同此心，顧人不自知、不自信爾。子曰：「書不盡言，言不盡意。」然則聖人之意，其不可見乎？子曰：「聖人立象以盡意，設卦以盡情偽，繋辭焉以盡其言，變而通以盡利，鼓之舞之以盡神。」至哉聖言，豈訓詁之所能解？既曰「書不盡言」矣，又曰「繋辭以盡言」；既曰「言不盡意」矣，又曰「立象以盡意」。於乎至哉！似矛盾而非矛盾也，似異而實同也。聖人之言意，豈盡不盡之所可言？言盡亦可，言不盡亦可。雲不盡者，聖人之實言；雲「盡」者，亦聖人之實言。此唯智者足以知其解者，始信「天下何思何慮」，始信「孔子無隱於二三子」，始信六十四卦卦卦齊一，始信「三百八十四爻爻爻不昧」。六十四卦皆可以言「元亨利貞」。聖人既於乾言之，又於坤言之，又於屯言之。聖人於此，謂學者可以意通之矣。故自蒙而下，或言其一，或言其二，或言其三，至隨又全言之，臨又言之，無妄、革又言之，亦偶於此數卦而復言，非此卦之特異也。亦恐學者執乾、坤、屯之卦異餘卦，故復於此言之，以破其疑。於坤曰「牝馬之貞」者，於以明地道也，妻道也，臣道也，柔順勤行之道也。剛上在陽，無為而佚，君之道也。柔陰在下，有為而勞，臣之道也。君臣之分不同，而道則同也。在君則剛、則佚，在臣則柔、則勞，一也。天下之動，貞夫一者也，無二貞也。子思曰：天地之道，其為物不二。使牝馬之貞果劣於乾，則屯不言牝馬，又其失實者猶多，而況於下焉者乎？易大傳曰：「古者包犧氏之王天下，仰則觀象於天，俯則觀法於地，觀鳥獸之文與地之宜，近取諸身，遠取諸物，於是始作八卦。」某嘗謂大傳非聖人作，於是乎益驗。此一章乃不知道者推測聖人意其如此甚矣。夫道之不明也久矣，未有一人知大傳之非者。惟「子曰」下乃聖人之言，餘則非。何以明此章之非？舜曰「道心」，明此心之即道，動乎意則失天性而為人心。孔子曰：「心之精神是謂聖」，禹曰「安汝止」，正明人心本寂然不動，動靜云為，乃此心之神用，如明鑑照物，大小遠近，參錯畢見，而非為也，非動也。天象、地法、鳥獸之文、地之宜，與凡在身及在物，皆在乎此心光明之中，非如此一章辭氣之勞也。此可與知道者語，未知道者必不信。楊氏易傳卷二十",-1)])])}const f=s(r,[["render",i]]);export{_ as __pageData,f as default};
